async function downloadHTML(){try{const response=await fetch(location.pathname);if(!response.ok)throw Error();const blob=await response.blob(),address=URL.createObjectURL(blob),a=document.createElement('a');a.href=address;a.download='UACS-Stellar-Atlas.html';a.click();setTimeout(()=>URL.revokeObjectURL(address),3000)}catch{const clone=document.documentElement.cloneNode(true);clone.querySelector('#scene').innerHTML='';clone.querySelector('#systemFocus').innerHTML='';clone.querySelectorAll('dialog').forEach(n=>n.removeAttribute('open'));const address=URL.createObjectURL(new Blob(['<!doctype html>\n'+clone.outerHTML],{type:'text/html'})),a=document.createElement('a');a.href=address;a.download='UACS-Stellar-Atlas.html';a.click();setTimeout(()=>URL.revokeObjectURL(address),3000)}}
